-- New Zealand milestone translations (ES/DE/FR)

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-anz-arrangement-2018', 'es', 'Acuerdo de facturación electrónica gubernamental Australia-Nueva Zelanda', 'Ambos gobiernos se comprometen con un enfoque compartido — la base de la especificación PINT A-NZ que ambos países utilizan ahora.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-anz-arrangement-2018', 'de', 'Australisch-neuseeländische Vereinbarung zur elektronischen Rechnungsstellung der Regierung', 'Beide Regierungen verpflichten sich zu einem gemeinsamen Ansatz — die Grundlage für die PINT-A-NZ-Spezifikation, die beide Länder heute verwenden.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-anz-arrangement-2018', 'fr', 'Accord australo-néo-zélandais sur la facturation électronique gouvernementale', 'Les deux gouvernements s''engagent dans une approche commune — la base de la spécification PINT A-NZ que les deux pays utilisent désormais.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-framework-2019', 'es', 'Se lanza el marco de facturación electrónica, junto con Australia', 'La infraestructura de facturación electrónica basada en Peppol de Nueva Zelanda entra en funcionamiento, con el MBIE establecido como la Autoridad Peppol nacional.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-framework-2019', 'de', 'E-Rechnungs-Rahmenwerk startet, gemeinsam mit Australien', 'Neuseelands Peppol-basierte E-Rechnungsinfrastruktur geht live, wobei das MBIE als nationale Peppol-Autorität eingerichtet wird.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-framework-2019', 'fr', 'Lancement du cadre de facturation électronique, aux côtés de l''Australie', 'L''infrastructure de facturation électronique basée sur Peppol de la Nouvelle-Zélande est mise en service, le MBIE étant désigné comme l''autorité Peppol nationale.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-central', 'es', 'Organismos del gobierno central obligados a recibir facturas electrónicas (en vigor desde marzo de 2022)', 'Todos los organismos públicos centrales han estado obligados a recibir facturas electrónicas Peppol desde marzo de 2022, administrado por el MBIE como la Autoridad Peppol de Nueva Zelanda.', '["Proveedores de organismos centrales: configuren la capacidad de facturación Peppol a través de un Punto de Acceso acreditado"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-central', 'de', 'Zentrale Regierungsbehörden müssen E-Rechnungen empfangen können (in Kraft seit März 2022)', 'Alle zentralen öffentlichen Behörden müssen seit März 2022 Peppol-E-Rechnungen empfangen können, verwaltet vom MBIE als Neuseelands Peppol-Autorität.', '["Lieferanten an zentrale Behörden: richten Sie die Peppol-Rechnungsfähigkeit über einen akkreditierten Access Point ein"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-central', 'fr', 'Les organismes du gouvernement central doivent recevoir des factures électroniques (en vigueur depuis mars 2022)', 'Tous les organismes publics centraux sont tenus de recevoir des factures électroniques Peppol depuis mars 2022, administré par le MBIE en tant qu''autorité Peppol de Nouvelle-Zélande.', '["Fournisseurs des organismes centraux : mettez en place la capacité de facturation Peppol via un point d''accès agréé"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-pint-anz-2025', 'es', 'PINT A-NZ se convierte en la única especificación aceptada', 'La extensión heredada A-NZ Peppol BIS Billing 3.0 se elimina por completo de la red utilizada por los Puntos de Acceso acreditados por el MBIE.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-pint-anz-2025', 'de', 'PINT A-NZ wird zur einzig akzeptierten Spezifikation', 'Die veraltete A-NZ-Peppol-BIS-Billing-3.0-Erweiterung wird vollständig aus dem von MBIE-akkreditierten Access Points genutzten Netzwerk entfernt.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-pint-anz-2025', 'fr', 'PINT A-NZ devient la seule spécification acceptée', 'L''extension héritée A-NZ Peppol BIS Billing 3.0 est entièrement retirée du réseau utilisé par les points d''accès agréés par le MBIE.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-5th-edition-announced-2025', 'es', 'Se anuncian las Reglas de Contratación Pública de Quinta Edición', 'El MBIE publica reglas actualizadas que amplían las obligaciones de facturación electrónica tanto para organismos como para grandes proveedores, junto con nuevos estándares de pago rápido.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-5th-edition-announced-2025', 'de', 'Fünfte Ausgabe der Government Procurement Rules angekündigt', 'Das MBIE veröffentlicht aktualisierte Regeln, die die E-Rechnungspflichten sowohl für Behörden als auch für Großlieferanten erweitern, zusammen mit neuen Standards für schnelle Zahlungen.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-5th-edition-announced-2025', 'fr', 'Annonce de la cinquième édition des règles de passation des marchés publics', 'Le MBIE publie des règles mises à jour élargissant les obligations de facturation électronique tant pour les organismes que pour les grands fournisseurs, ainsi que de nouvelles normes de paiement rapide.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-5th-edition-effect-2025', 'es', 'Entran en vigor las reglas de Quinta Edición', 'Las nuevas expectativas de facturación electrónica B2G quedan formalmente integradas en la práctica de contratación del sector público.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-5th-edition-effect-2025', 'de', 'Regeln der fünften Ausgabe treten in Kraft', 'Die neuen B2G-E-Rechnungserwartungen werden formell in die Beschaffungspraxis des öffentlichen Sektors integriert.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-5th-edition-effect-2025', 'fr', 'Entrée en vigueur des règles de la cinquième édition', 'Les nouvelles attentes en matière de facturation électronique B2G sont formellement intégrées dans la pratique de passation des marchés du secteur public.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-2000', 'es', 'Los organismos que gestionan 2.000+ facturas/año deben enviar y recibir facturas electrónicas', 'Los organismos gubernamentales que procesan más de 2.000 facturas comerciales nacionales anualmente deben tener plena capacidad tanto para enviar como para recibir facturas electrónicas estructuradas, y pagar el 95% de ellas en un plazo de 5 días hábiles.', '["Confirme el cumplimiento del formato PINT A-NZ — obligatorio para la facturación electrónica gubernamental desde mayo de 2025", "Compruebe si su cliente gubernamental se encuentra dentro de este umbral de volumen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-2000', 'de', 'Behörden mit 2.000+ Rechnungen/Jahr müssen E-Rechnungen senden & empfangen können', 'Regierungsbehörden, die jährlich mehr als 2.000 inländische Handelsrechnungen bearbeiten, müssen vollständig in der Lage sein, strukturierte E-Rechnungen zu senden und zu empfangen, und müssen 95 % davon innerhalb von 5 Geschäftstagen bezahlen.', '["Bestätigen Sie die PINT-A-NZ-Formatkonformität — verpflichtend für die staatliche E-Rechnungsstellung seit Mai 2025", "Prüfen Sie, ob Ihr Regierungskunde innerhalb dieser Volumenschwelle liegt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-2000', 'fr', 'Les organismes traitant 2 000+ factures/an doivent envoyer et recevoir des factures électroniques', 'Les organismes gouvernementaux traitant plus de 2 000 factures commerciales nationales par an doivent être pleinement capables d''envoyer et de recevoir des factures électroniques structurées, et de payer 95 % d''entre elles dans un délai de 5 jours ouvrables.', '["Confirmez la conformité au format PINT A-NZ — obligatoire pour la facturation électronique gouvernementale depuis mai 2025", "Vérifiez si votre client gouvernemental se situe dans ce seuil de volume"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-largesupplier', 'es', 'Los grandes proveedores (>33 millones NZD de facturación) deben enviar facturas electrónicas al gobierno', 'Los proveedores con una facturación superior a 33 millones de NZD en cada uno de los dos años contables anteriores deben enviar facturas electrónicas a través de Peppol para facturas comerciales nacionales a compradores gubernamentales.', '["Evalúe si su facturación supera el umbral de 33 millones de NZD", "Intégrese con un Punto de Acceso Peppol con suficiente antelación a la fecha límite"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-largesupplier', 'de', 'Großlieferanten (>NZD 33 Mio. Umsatz) müssen E-Rechnungen an die Regierung übermitteln', 'Lieferanten mit einem Umsatz von mehr als NZD 33 Millionen in jedem der beiden vorangegangenen Rechnungsjahre müssen E-Rechnungen über Peppol für inländische Handelsrechnungen an staatliche Käufer übermitteln.', '["Bewerten Sie, ob Ihr Umsatz die Schwelle von NZD 33 Millionen überschreitet", "Integrieren Sie sich rechtzeitig vor der Frist mit einem Peppol Access Point"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nz-largesupplier', 'fr', 'Les grands fournisseurs (>33 M NZD de chiffre d''affaires) doivent soumettre des factures électroniques au gouvernement', 'Les fournisseurs dont le chiffre d''affaires dépasse 33 millions de NZD au cours de chacune des deux années comptables précédentes doivent soumettre des factures électroniques via Peppol pour les factures commerciales nationales aux acheteurs gouvernementaux.', '["Évaluez si votre chiffre d''affaires dépasse le seuil de 33 millions de NZD", "Intégrez-vous à un point d''accès Peppol bien avant l''échéance"]');
